mapper.select:
SELECT A.PLAY_DAY, A.PLAY_CNT, B.SINGER_NM, B.REAL_FILE_NM AS orignlFileNm, B.FILE_ALBUM, B.FILE_ALBUM_REGDATE, C.CENTER_NM FROM TB_BASICFILEGROUP_PLAYINFO A JOIN LETTNFILEDETAIL B ON A.ATCH_FILE_ID = B.ATCH_FILE_ID JOIN TB_CENTERINFO C ON A.CENTER_ID = C.CENTER_ID WHERE 1=1
AND A.PLAY_DAY BETWEEN #{searchStartDay} AND #{searchEndDay}
AND A.CENTER_ID IN
#{item}
GROUP BY A.PLAY_DAY, A.PLAY_CNT, B.SINGER_NM, B.REAL_FILE_NM, B.FILE_ALBUM, B.FILE_ALBUM_REGDATE, C.CENTER_NM ORDER BY C.CENTER_NM ASC, A.PLAY_DAY ASC

SELECT B.REAL_FILE_NM AS ORIGNL_FILE_NM, B.SINGER_NM, B.FILE_ALBUM, B.FILE_ALBUM_REGDATE, SUM(A.PLAY_CNT) AS PLAY_CNT FROM TB_BASICFILEGROUP_PLAYINFO A JOIN LETTNFILEDETAIL B ON A.ATCH_FILE_ID = B.ATCH_FILE_ID WHERE 1=1
AND A.PLAY_DAY BETWEEN #{searchStartDay} AND #{searchEndDay}
AND A.CENTER_ID IN
#{item}
GROUP BY B.REAL_FILE_NM, B.SINGER_NM, B.FILE_ALBUM, B.FILE_ALBUM_REGDATE ORDER BY REAL_FILE_NM ASC

SELECT COALESCE(COUNT(*), 0)
FROM TB_BASICFILEGROUP_PLAYINFO
WHERE CENTER_ID = #{centerId}
  AND PLAY_DAY = #{playDay}
  AND ATCH_FILE_ID = #{atchFileId}

